public with sharing class MyContactListController {
    @AuraEnabled
    public static List<Contact> getContacts(Id recordId) {
        return [SELECT Id, FirstName, LastName, Email, Phone
                FROM Contact WHERE AccountId = :recordId];
    }
}

({
    myAction : function(component, event, helper) {
        var action = component.get("c.getContacts");          // c. = Apex 메서드
        action.setParams({ recordId: component.get("v.recordId") });
        action.setCallback(this, function(data) {
            component.set("v.Contacts", data.getReturnValue());
        });
        $A.enqueueAction(action);                              // 서버 호출 대기열에 넣기
    }
})

component.set("v.Columns", [
    {label:"First Name", fieldName:"FirstName", type:"text"},
    {label:"Last Name",  fieldName:"LastName",  type:"text"},
    {label:"Phone",      fieldName:"Phone",     type:"phone"}
]);
